/* ════════════════════════════════════════════════════════════
 * AUDIO HELPERS
 * ════════════════════════════════════════════════════════════ */
static int meow_idx = -1;   /* -1 = idle */

static void audio_init(void)
{
    *audio_ctrl_r = 0x0C;   /* clear both FIFOs */
    *audio_ctrl_r = 0x00;
}

/* Non-blocking: push as many samples as the FIFO currently accepts.
 * Call once per main-loop iteration.                               */
static void audio_service(void)
{
    if (meow_idx < 0) return;
    int fifo = *audio_fifo_r;
    int wsc  = (fifo >> 8) & 0xFF;   /* write spaces available */
    while (wsc > 0 && meow_idx < MEOW_SAMPLE_COUNT) {
        int s      = meow_samples[meow_idx++] << 8;  // ← ADD THIS SHIFT
        *audio_l_r = s;
        *audio_r_r = s;
        wsc--;
    }
    if (meow_idx >= MEOW_SAMPLE_COUNT) meow_idx = -1;
}

/* Call to start (or restart) the meow from the beginning */
static void meow_play(void) { meow_idx = 0; }

