    fill_rect(cx-6,cy+10,4,12,P_PANTS); fill_rect(cx+2,cy+10,4,12,P_PANTS);
    fill_rect(cx-7,cy-2,14,13,P_SHIRT);
    fill_rect(cx-2,cy-2,4,3,P_SKIN);
    fill_rect(cx-10,cy+1,3,9,P_SHIRT);
