/* ════════════════════════════════════════════════════════════
 * SPRITE BG SAVE/RESTORE
 * ════════════════════════════════════════════════════════════ */
#define SPRITE_W  31
#define SPRITE_H  48
#define SPRITE_X0 (-15)
#define SPRITE_Y0 (-23)
static short bg_patch[SPRITE_H][SPRITE_W];

void save_bg(int cx, int cy)
{
    int px,py,bx,by;
    for(by=0;by<SPRITE_H;by++){
        py=cy+SPRITE_Y0+by;
        for(bx=0;bx<SPRITE_W;bx++){
            px=cx+SPRITE_X0+bx;
            bg_patch[by][bx]=(px>=0&&px<320&&py>=0&&py<240)?pixel_buf[py*512+px]:0;
        }
    }
}
void restore_bg(int cx, int cy)
{
    int px,py,bx,by;
    for(by=0;by<SPRITE_H;by++){
        py=cy+SPRITE_Y0+by;
        for(bx=0;bx<SPRITE_W;bx++){
            px=cx+SPRITE_X0+bx;
            if(px>=0&&px<320&&py>=0&&py<240) pixel_buf[py*512+px]=bg_patch[by][bx];
        }
    }
}

/* ════════════════════════════════════════════════════════════
 * FOOD ITEMS & BOXES
 * ════════════════════════════════════════════════════════════ */
void draw_food_box(int cx, int cy, int selected)
{
    short bg=selected?BOX_SEL:BOX_GREY, hi=selected?0x67E0:WHITE;
    fill_rect(cx-21,cy-18,42,36,bg);
    draw_rect_border(cx-21,cy-18,42,36,BLACK);
    draw_rect_border(cx-20,cy-17,40,34,hi);
}
void draw_food_fish(int cx, int cy)
{
    int fx=cx-4;
    fill_triangle(fx+11,cy,fx+18,cy-6,fx+18,cy+6,F_FISH_B);
    fill_circle(fx,cy,11,7,F_FISH_B); fill_circle(fx-2,cy+1,7,5,F_FISH_L);
    fill_triangle(fx-1,cy-7,fx+5,cy-7,fx+2,cy-12,F_FISH_B);
    fill_circle(fx-6,cy-2,3,3,WHITE); fill_circle(fx-6,cy-2,1,2,BLACK);
    plot_pixel(fx-5,cy-3,WHITE);
}
void draw_food_bone(int cx, int cy)
{
    fill_circle(cx-10,cy-3,6,5,MID_GREY); fill_circle(cx-10,cy+3,6,5,MID_GREY);
    fill_circle(cx+10,cy-3,6,5,MID_GREY); fill_circle(cx+10,cy+3,6,5,MID_GREY);
    fill_rect(cx-10,cy-4,20,8,MID_GREY);
    fill_circle(cx-10,cy-3,5,4,F_BONE); fill_circle(cx-10,cy+3,5,4,F_BONE);
    fill_circle(cx+10,cy-3,5,4,F_BONE); fill_circle(cx+10,cy+3,5,4,F_BONE);
    fill_rect(cx-9,cy-2,18,5,F_BONE);
}
void draw_food_seeds(int cx, int cy)
{
    fill_circle(cx,cy+6,12,4,MID_GREY);
    int sx[10]={-6,-2,2,6,-5,1,4,-1,3,-4};
    int sy[10]={2,1,3,2,5,5,6,7,0,-1};
    int s;
    for(s=0;s<10;s++){fill_circle(cx+sx[s],cy+sy[s],2,2,F_SEED_L);plot_pixel(cx+sx[s],cy+sy[s],F_SEED_D);}
}
void draw_food_carrot(int cx, int cy)
{
    fill_triangle(cx-7,cy-10,cx+7,cy-10,cx,cy+10,F_CARROT);
    draw_line(cx-5,cy-5,cx+5,cy-5,0xE480); draw_line(cx-4,cy,cx+4,cy,0xE480); draw_line(cx-2,cy+5,cx+2,cy+5,0xE480);
    fill_triangle(cx,cy-10,cx-6,cy-19,cx-1,cy-12,F_LEAF);
    fill_triangle(cx,cy-10,cx+6,cy-19,cx+1,cy-12,F_LEAF);
    fill_triangle(cx-1,cy-10,cx-2,cy-16,cx+3,cy-13,F_LEAF);
}
void redraw_food_slot(int slot, int carried_food)
{
    int cx;
    if(slot==0)cx=F0_X; else if(slot==1)cx=F1_X; else if(slot==2)cx=F2_X; else cx=F3_X;
    int selected=(carried_food==slot);
    draw_food_box(cx,FOOD_Y,selected);
    if(slot==0)draw_food_fish(cx,FOOD_Y);
    else if(slot==1)draw_food_bone(cx,FOOD_Y);
    else if(slot==2)draw_food_seeds(cx,FOOD_Y);
    else draw_food_carrot(cx,FOOD_Y);
}
int check_food_collision(int px, int py)
{
    if(py<168) return -1;
    int food_xs[4]={F0_X,F1_X,F2_X,F3_X},i;
    for(i=0;i<4;i++){int dx=px-food_xs[i];if(dx<0)dx=-dx;if(dx<=21)return i;}
    return -1;
}
int check_dropoff(int px, int py, int animal_id)
{
    if(animal_id<0||py>DROPOFF_Y_MAX) return 0;
    int dx=px-animal_cx[animal_id]; if(dx<0)dx=-dx;
    return (dx<=26);
}

/* ════════════════════════════════════════════════════════════
 * PS/2
 * ════════════════════════════════════════════════════════════ */
int ps2_read_byte(void){int d=*ps2_ptr;return(d&0x8000)?(d&0xFF):-1;}
void ps2_flush(void){int t=10000;while(t-->0){int d=*ps2_ptr;if(!(d&0x8000))break;}}
void wait_any_key(void)
{
    int ext=0,brk=0;
    while(1){
        int b=ps2_read_byte(); if(b<0)continue;
        if(b==PS2_EXT){ext=1;continue;} if(b==PS2_BREAK){brk=1;continue;}
        if(brk){brk=0;ext=0;continue;} ext=0; return;
    }
}

/* ════════════════════════════════════════════════════════════
 * START SCREEN
 * ════════════════════════════════════════════════════════════ */
void draw_start_screen(void)
{
    fill_rect(0,0,320,240,0x0821);
    draw_rect_border(4,4,312,232,0xFFE0); draw_rect_border(8,8,304,224,0xFD60); draw_rect_border(12,12,296,216,0xFFE0);
    draw_label_large(44,30,"PET",0xFFE0); draw_label_large(44,50,"CAFE",0xFD60); draw_label_large(44,70,"GAME",WHITE);
    draw_cat(50,135); draw_dog(100,135); draw_bird(150,135); draw_hamster(200,135); draw_rabbit(250,135);
    draw_label(55,165,"FEED THE RIGHT ANIMAL",0xFFE0);
    draw_label(70,175,"WITH THE RIGHT FOOD",0xFD60);
    draw_label(60,190,"USE ARROW KEYS TO MOVE",LIGHT_GREY);
    draw_label(72,210,"PRESS ANY KEY TO START",0x07FF);
    fill_circle(30,215,3,3,0xFFE0); fill_circle(290,215,3,3,0xFFE0);
}

/* ════════════════════════════════════════════════════════════
 * END SCREEN
 * ════════════════════════════════════════════════════════════ */
void draw_end_screen(int score)
{
    fill_rect(0,0,320,240,0x0821);
    draw_rect_border(4,4,312,232,0xFFE0); draw_rect_border(8,8,304,224,0xFD60); draw_rect_border(12,12,296,216,0xFFE0);
    draw_label_large(30,30,"GAME",0xF800); draw_label_large(30,50,"OVER",0xF800); draw_label_large(30,70,"!",0xFFE0);
    draw_label(70,105,"YOUR SCORE",WHITE); draw_label(70,118,"WAS",WHITE);
    char sbuf[8]; int idx=0,val=score;
    if(val<0){sbuf[idx++]='-';val=-val;}
    if(val>=100){sbuf[idx++]='0'+(val/100);val%=100;sbuf[idx++]='0'+(val/10);val%=10;sbuf[idx++]='0'+val;}
    else if(val>=10){sbuf[idx++]='0'+(val/10);val%=10;sbuf[idx++]='0'+val;}
    else sbuf[idx++]='0'+val;
    sbuf[idx]='\0';
    draw_label_large(120,112,sbuf,0xFFE0);
    if(score>=10)draw_label(75,155,"AMAZING WORK",0x07E0);
    else if(score>=5){draw_label(72,155,"GOOD JOB KEEP",0xFFE0);draw_label(72,165,"IT UP",0xFFE0);}
    else if(score>=1)draw_label(72,155,"NICE TRY",0xFD60);
    else{draw_label(66,155,"BETTER LUCK NEXT",0xF800);draw_label(66,165,"TIME",0xF800);}
    draw_cat(50,115); draw_rabbit(270,115);
    draw_label(66,200,"PRESS ANY KEY TO PLAY",0x07FF);
    draw_label(90,210,"AGAIN",0x07FF);
}

/* ════════════════════════════════════════════════════════════
 * GAME SCENE
 * ════════════════════════════════════════════════════════════ */
void draw_game_scene(void)
{
    draw_background(); draw_hud(); draw_all_stalls(); draw_title_banner();
    draw_cat(P_CX_0,PET_Y); draw_dog(P_CX_1,PET_Y); draw_bird(P_CX_2,PET_Y);
    draw_hamster(P_CX_3,PET_Y); draw_rabbit(P_CX_4,PET_Y);
    draw_label(P_CX_0-8, STALL_BOT+2,"CAT",    BLACK);
    draw_label(P_CX_1-8, STALL_BOT+2,"DOG",    BLACK);
    draw_label(P_CX_2-10,STALL_BOT+2,"BIRD",   BLACK);
    draw_label(P_CX_3-22,STALL_BOT+2,"HAMSTER",BLACK);
    draw_label(P_CX_4-16,STALL_BOT+2,"RABBIT", BLACK);
    draw_food_box(F0_X,FOOD_Y,0); draw_food_box(F1_X,FOOD_Y,0);
    draw_food_box(F2_X,FOOD_Y,0); draw_food_box(F3_X,FOOD_Y,0);
    draw_food_fish(F0_X,FOOD_Y); draw_food_bone(F1_X,FOOD_Y);
    draw_food_seeds(F2_X,FOOD_Y); draw_food_carrot(F3_X,FOOD_Y);
    draw_label(F0_X-14,FOOD_Y+21,"FISH",  WHITE);
    draw_label(F1_X-14,FOOD_Y+21,"BONE",  WHITE);
    draw_label(F2_X-14,FOOD_Y+21,"SEEDS", WHITE);
    draw_label(F3_X-20,FOOD_Y+21,"CARROT",WHITE);
}

int pick_new_animal(int current)
{
    int next;
    do { next=rand_range(5); } while(next==current);
    return next;
}

/* ════════════════════════════════════════════════════════════
 * MAIN
 * ════════════════════════════════════════════════════════════ */
int main(void)
{
    *(vga_ctrl+1) = PIXEL_BASE;
    audio_init();   /* clear audio FIFOs */

    int game_state=STATE_START;
    int score=0, carried=FOOD_NONE;
    int player_x=160, player_y=162;
    int active_animal=-1, prev_food=-1;
    int ext_pending=0, break_pending=0;

    while(1)
    {
        /* ── Service audio on every iteration ──────────── */
        audio_service();

        /* ════════════════════════
         * START SCREEN
         * ════════════════════════ */
        if(game_state==STATE_START)
        {
            draw_start_screen();
            ps2_flush();
            wait_any_key();

            score=0; carried=FOOD_NONE;
            player_x=160; player_y=162;
            prev_food=-1; ext_pending=0; break_pending=0;

            draw_game_scene();
            draw_score(score);

            active_animal=rand_range(5);
            draw_stall_highlight(active_animal,1);
            draw_animal(active_animal,animal_cx[active_animal],PET_Y);

            /* Play meow if first animal is the cat */
            if(active_animal==0) meow_play();

            save_bg(player_x,player_y);
            draw_human(player_x,player_y);

            game_state=STATE_PLAY;
            continue;
        }

        /* ════════════════════════
         * END SCREEN
         * ════════════════════════ */
        if(game_state==STATE_END)
        {
            draw_end_screen(score);
            ps2_flush();
            wait_any_key();
            game_state=STATE_START;
            continue;
        }

        /* ════════════════════════
         * GAMEPLAY
         * ════════════════════════ */

        /* Food pick-up */
        int food_hit=check_food_collision(player_x,player_y);
        if(food_hit!=prev_food){
            if(food_hit>=0&&carried==FOOD_NONE){
                restore_bg(player_x,player_y);
                carried=food_hit;
                redraw_food_slot(food_hit,carried);
                save_bg(player_x,player_y);
                draw_human(player_x,player_y);
            }
            prev_food=food_hit;
        }

        /* Drop-off at animal stall */
        if(carried!=FOOD_NONE&&check_dropoff(player_x,player_y,active_animal))
        {
            if(carried==correct_food[active_animal]) score++;
            else                                      score--;

            restore_bg(player_x,player_y);

            int old_carried=carried;
            carried=FOOD_NONE;
            redraw_food_slot(old_carried,FOOD_NONE);

            draw_stall_highlight(active_animal,0);
            draw_animal(active_animal,animal_cx[active_animal],PET_Y);

            /* Pick new animal and highlight */
            active_animal=pick_new_animal(active_animal);
            draw_stall_highlight(active_animal,1);
            draw_animal(active_animal,animal_cx[active_animal],PET_Y);

            /* ── Play meow if newly highlighted animal is the cat ── */
            if(active_animal==0) meow_play();

            draw_score(score);

            save_bg(player_x,player_y);
            draw_human(player_x,player_y);

            if(score>=10||score<=-5) game_state=STATE_END;
            continue;
        }

        /* PS/2 input */
        int byte=ps2_read_byte();
        if(byte<0) continue;

        if(byte==PS2_EXT)  {ext_pending=1;  continue;}
        if(byte==PS2_BREAK){break_pending=1; continue;}
        if(break_pending){break_pending=0;ext_pending=0;continue;}

        if(ext_pending){
            ext_pending=0;
            int new_x=player_x, new_y=player_y;
            switch(byte){
                case SC_LEFT:  new_x-=MOVE_STEP; break;
                case SC_RIGHT: new_x+=MOVE_STEP; break;
                case SC_UP:    new_y-=MOVE_STEP; break;
                case SC_DOWN:  new_y+=MOVE_STEP; break;
                default: continue;
            }
            if(new_x<PLAYER_X_MIN)new_x=PLAYER_X_MIN;
            if(new_x>PLAYER_X_MAX)new_x=PLAYER_X_MAX;
            if(new_y<PLAYER_Y_MIN)new_y=PLAYER_Y_MIN;
            if(new_y>PLAYER_Y_MAX)new_y=PLAYER_Y_MAX;
            if(new_x!=player_x||new_y!=player_y){
                restore_bg(player_x,player_y);
                player_x=new_x; player_y=new_y;
                save_bg(player_x,player_y);
                draw_human(player_x,player_y);
            }
        }
    }
    return 0;
}